const body = $input.first().json.body ?? $input.first().json;
const doc = body.event?.data?.new ?? body;

if (doc.tipo !== 'cotizacion') {
  throw new Error('El documento no es una cotización');
}
if (doc.mime_type !== 'application/pdf') {
  throw new Error('Esta versión solo lee PDF; el archivo es ' + doc.mime_type);
}

return [{ json: {
  documento_id: doc.id,
  solicitud_id: doc.solicitud_id,
  proveedor_id: doc.proveedor_id,
  version_recibida: doc.version ?? null
} }];

const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const MAX = 32 * 1024 * 1024;
if (buf.length > MAX) {
  throw new Error('El PDF supera 32 MB; dividirlo antes de leerlo');
}

const instrucciones = `Eres un asistente que extrae datos de cotizaciones de obra en soles o dólares.
Lee el PDF adjunto y devuelve SOLO los datos que aparecen escritos.

Reglas:
- No inventes valores. Si un dato no aparece, devuelve null.
- Copia los precios tal como figuran. Indica en igv_incluido si el documento dice que el precio incluye IGV; si no lo dice, usa null.
- Indica la página de cada ítem en pagina.
- Si una línea es ambigua o ilegible, marca requiere_revision como true y explícalo en observacion.
- version: usa "preliminar", "corregida" o "final" solo si el documento lo dice; si no, null.`;

return [{ json: {
  model: 'claude-opus-5-5',
  max_tokens: 16000,
  output_config: {
    effort: 'low',
    format: {
      type: 'json_schema',
      schema: {
        type: 'object',
        additionalProperties: false,
        required: ['cabecera', 'items', 'requiere_revision'],
        properties: {
          cabecera: {
            type: 'object',
            additionalProperties: false,
            required: ['proveedor_nombre', 'ruc', 'fecha', 'moneda', 'validez_dias', 'plazo_dias', 'forma_pago', 'garantia_meses', 'version'],
            properties: {
              proveedor_nombre: { type: ['string', 'null'] },
              ruc: { type: ['string', 'null'] },
              fecha: { type: ['string', 'null'] },
              moneda: { type: ['string', 'null'] },
              validez_dias: { type: ['integer', 'null'] },
              plazo_dias: { type: ['integer', 'null'] },
              forma_pago: { type: ['string', 'null'] },
              garantia_meses: { type: ['integer', 'null'] },
              version: { type: ['string', 'null'], enum: ['preliminar', 'corregida', 'final', null] }
            }
          },
          items: {
            type: 'array',
            items: {
              type: 'object',
              additionalProperties: false,
              required: ['codigo', 'descripcion', 'unidad', 'cantidad', 'precio_unitario', 'total', 'igv_incluido', 'pagina', 'observacion'],
              properties: {
                codigo: { type: ['string', 'null'] },
                descripcion: { type: 'string' },
                unidad: { type: ['string', 'null'] },
                cantidad: { type: ['number', 'null'] },
                precio_unitario: { type: ['number', 'null'] },
                total: { type: ['number', 'null'] },
                igv_incluido: { type: ['boolean', 'null'] },
                pagina: { type: ['integer', 'null'] },
                observacion: { type: ['string', 'null'] }
              }
            }
          },
          requiere_revision: { type: 'boolean' }
        }
      }
    }
  },
  messages: [{
    role: 'user',
    content: [
      { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: buf.toString('base64') } },
      { type: 'text', text: instrucciones }
    ]
  }]
} }];

const r = $input.first().json;

if (r.stop_reason === 'refusal') {
  return [{ json: { estado: 'revision_manual', motivo: 'Claude declinó procesar el documento', ...r.stop_details } }];
}
if (r.stop_reason === 'max_tokens') {
  return [{ json: { estado: 'revision_manual', motivo: 'La respuesta se cortó: el documento tiene demasiados ítems' } }];
}

const texto = r.content.find(b => b.type === 'text')?.text;
const datos = JSON.parse(texto);

return [{ json: {
  estado: datos.requiere_revision ? 'revision_manual' : 'extraido',
  cabecera: datos.cabecera,
  items: datos.items,
  uso: r.usage
} }];
